
.wrap {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── Bento 方格 ── */
.bento {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.cell {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 12px;
  border-radius: 12px;
  background: var(--c-sunken);
}

.cell__k {
  font-size: 12px;
  font-weight: 400;
  color: var(--c-text-faint);
  flex-shrink: 0;
}

.cell__v {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cell__v--num {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-size: 11.5px;
}

/* ── 资源等级卡 ── */
.rank {
  padding: 16px;
  border: 1px solid var(--c-border);
  border-radius: 16px;
  background: var(--c-bar);
}

.rank__tag {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--c-text-faint);
}

.rank__title {
  margin: 4px 0 2px;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.5px;
  line-height: 1.15;
  color: var(--c-text);
}

.rank__sub {
  font-size: 11.5px;
  color: var(--c-text-muted);
  line-height: 1.5;
}

/* ── 指标 ── */
.metrics {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.metric__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.metric__k {
  font-size: 11.5px;
  color: var(--c-text-muted);
}

.metric__v {
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-weight: 600;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.track {
  height: 6px;
  border-radius: 3px;
  background: var(--c-border);
  overflow: hidden;
}

.track__fill {
  height: 100%;
  border-radius: 3px;
  background: var(--c-text);
  transition: width 0.5s var(--ease);
}

.track__fill--light {
  background: var(--c-text-faint);
}

/* ── 文本卡 ── */
.bio {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px 14px;
  border-radius: 14px;
  background: var(--c-sunken);
}

.bio__row {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.bio__k {
  font-size: 10.5px;
  font-weight: 600;
  color: var(--c-text-faint);
}

.bio__v {
  font-size: 12px;
  line-height: 1.5;
  color: #3a3a3c;
  white-space: pre-wrap;
}
