
.wrap {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── 风评卡 ── */
.rank {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 16px;
  border: 1px solid var(--c-border);
  border-radius: 16px;
  background: var(--c-bar);
}

.rank__tag {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--c-text-faint);
}

.rank__hero {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}

.rank__n {
  font-family: var(--font-mono);
  font-size: 42px;
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--c-text);
}

.rank__n--hot {
  color: var(--c-danger);
}

.rank__u {
  font-size: 12px;
  color: var(--c-text-muted);
}

.tag {
  margin-left: auto;
  font-size: 10.5px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--c-sunken);
  white-space: nowrap;
}

.tag--ok {
  color: var(--c-success);
}

.tag--mid {
  color: var(--c-text-muted);
}

.tag--warn {
  color: var(--c-warning);
}

.tag--bad {
  color: var(--c-danger);
}

.crisis {
  display: flex;
  align-items: baseline;
  gap: 9px;
  margin-top: 4px;
  padding: 9px 12px;
  border-radius: var(--radius-sm);
  background: #fff1f2;
}

.crisis__k {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--c-danger);
  flex-shrink: 0;
}

.crisis__v {
  font-size: 12px;
  color: var(--c-danger);
  line-height: 1.55;
}

/* ── 卡片 ── */
.card {
  padding: 14px;
  border: 1px solid var(--c-border);
  border-radius: 16px;
  background: #ffffff;
}

.card__h {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--c-text-faint);
  margin-bottom: 10px;
}

.issues {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.issue {
  position: relative;
  padding-left: 13px;
  font-size: 12.5px;
  color: var(--c-text);
  line-height: 1.65;

  &::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0.66em;
    width: 3.5px;
    height: 3.5px;
    border-radius: 50%;
    background: var(--c-text-faint);
  }
}

/* ── 粉丝 ── */
.fan__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.fan__size {
  font-size: 13px;
  font-weight: 600;
  color: var(--c-text);
}

.fan__power {
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-weight: 600;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
}

.comp {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 18px;
  margin-top: 14px;
}

.comp__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 4px;
}

.comp__k {
  font-size: 11px;
  color: var(--c-text-faint);
}

.comp__v {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
}

.comp__track {
  height: 4px;
}

.track {
  height: 6px;
  border-radius: 3px;
  background: var(--c-border);
  overflow: hidden;
}

.track__fill {
  height: 100%;
  border-radius: 3px;
  background: var(--c-text);
  transition: width 0.5s var(--ease);
}

.track__fill--light {
  background: var(--c-text-faint);
}

.track__fill--warn {
  background: var(--c-warning);
}

.track__fill--danger {
  background: var(--c-danger);
}

.hint {
  padding: 3px 0;
  text-align: center;
  font-size: 12px;
  color: var(--c-text-faint);
}
