
.ap-scope {
  width: 100%;
  max-width: 880px;
  margin: 0 auto;
  font-family: var(--font-ui);
  user-select: none;
  font-weight: 500;
}

/* ══ 折叠态：液态玻璃悬浮岛 ══ */
.ap-island {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  height: 44px;
  padding: 0 18px;
  border: 1px solid var(--c-glass-edge);
  border-radius: 999px;
  background: var(--c-glass);
  backdrop-filter: var(--glass);
  -webkit-backdrop-filter: var(--glass);
  box-shadow:
    var(--lift),
    inset 0 1px 0 #ffffff;
  color: var(--c-text);
  font-family: var(--font-ui);
  cursor: pointer;
  overflow: hidden;
  transition:
    border-radius 0.45s var(--ease),
    box-shadow 0.3s ease,
    transform 0.3s var(--ease);
  -webkit-tap-highlight-color: transparent;
}

.ap-island:hover {
  transform: translateY(-1px);
  box-shadow:
    var(--lift-hi),
    inset 0 1px 0 #ffffff;
}

.ap-island--open {
  border-radius: 24px 24px 0 0;
  border-bottom-color: transparent;
  box-shadow: var(--lift);
}

.ap-island__sheen {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    100deg,
    transparent 20%,
    rgba(255, 255, 255, 0.9) 42%,
    rgba(255, 255, 255, 0) 58%
  );
  opacity: 0.5;
}

.ap-island__led {
  position: relative;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.ap-island__led--ok {
  background: var(--c-ok);
  box-shadow: 0 0 7px rgba(52, 199, 89, 0.6);
}

.ap-island__led--warn {
  background: var(--c-warning);
  box-shadow: 0 0 7px rgba(201, 120, 10, 0.55);
}

.ap-island__led--bad {
  background: var(--c-danger);
  box-shadow: 0 0 7px rgba(224, 52, 43, 0.55);
}

.ap-island__name {
  position: relative;
  font-size: 13.5px;
  font-weight: 700;
  letter-spacing: -0.015em;
  white-space: nowrap;
  flex-shrink: 0;
}

.ap-island__role {
  position: relative;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--c-text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1 1 auto;
  min-width: 0;
}

.ap-island__clock {
  position: relative;
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-weight: 550;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

.ap-island__caret {
  position: relative;
  width: 15px;
  height: 15px;
  stroke: var(--c-text-faint);
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
  transition: transform 0.4s var(--ease);
}

.ap-island__caret--up {
  transform: rotate(180deg);
}

/* ══ 展开态 ══ */
.ap-stage {
  display: grid;
  grid-template-rows: 0fr;
  transition:
    grid-template-rows 0.5s var(--ease),
    opacity 0.32s ease;
  opacity: 0;
}

.ap-stage--open {
  grid-template-rows: 1fr;
  opacity: 1;
}

.ap-stage__clip {
  min-height: 0;
  overflow: hidden;
}

/* 4:3 画幅 */
.ap-frame {
  display: grid;
  grid-template-rows: auto 1fr auto;
  width: 100%;
  aspect-ratio: 4 / 3;
  border: 1px solid var(--c-glass-edge);
  border-top: none;
  border-radius: 0 0 24px 24px;
  background: var(--c-shell);
  backdrop-filter: var(--glass);
  -webkit-backdrop-filter: var(--glass);
  box-shadow: var(--lift-hi);
  overflow: hidden;
}

/* ── 顶部胶囊栏 ── */
.ap-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 18px;
  background: var(--c-bar);
  border-bottom: 0.5px solid #efefef;
}

.ap-top__left {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.ap-top__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.ap-top__dot--ok {
  background: var(--c-ok);
  box-shadow: 0 0 8px rgba(52, 199, 89, 0.5);
}

.ap-top__dot--warn {
  background: var(--c-warning);
  box-shadow: 0 0 8px rgba(201, 120, 10, 0.45);
}

.ap-top__dot--bad {
  background: var(--c-danger);
  box-shadow: 0 0 8px rgba(224, 52, 43, 0.45);
}

.ap-top__name {
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: -0.012em;
  color: var(--c-text);
  white-space: nowrap;
}

.ap-top__center {
  display: flex;
  gap: 6px;
  overflow: hidden;
  min-width: 0;
}

.ap-top__right {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 550;
  color: var(--c-text-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  flex-shrink: 0;
}

.ap-pill {
  font-size: 10.5px;
  font-weight: 400;
  padding: 2px 8px;
  border-radius: 12px;
  background: #efeff4;
  color: var(--c-text-faint);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ap-pill--on {
  background: #ebf3ff;
  color: var(--c-primary);
  font-weight: 500;
}

/* ── 分栏 ── */
.ap-split {
  display: flex;
  min-height: 0;
  overflow: hidden;
}

/* 左：图标竖排 */
.ap-sidebar {
  width: 82px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px 8px;
  background: var(--c-rail);
  border-right: 0.5px solid var(--c-border);
  overflow-y: auto;
  scrollbar-width: none;

  &::-webkit-scrollbar {
    display: none;
  }
}

.ap-nav {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 10px 4px;
  border: none;
  border-radius: 14px;
  background: transparent;
  color: var(--c-text-faint);
  font-family: var(--font-ui);
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.25s var(--ease);
  -webkit-tap-highlight-color: transparent;

  &:hover {
    background: rgba(0, 0, 0, 0.03);
    color: var(--c-text);
  }

  :deep(svg) {
    width: 18px;
    height: 18px;
    stroke: currentColor;
    stroke-width: 1.5;
    fill: none;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
}

.ap-nav__icon {
  width: 18px;
  height: 18px;
  display: block;
}

.ap-nav__label {
  font-size: 11px;
  font-weight: 500;
}

.ap-nav--on {
  background: #ffffff;
  color: var(--c-primary);
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.06);

  .ap-nav__label {
    font-weight: 600;
  }
}

.ap-sidebar__foot {
  margin-top: auto;
  padding-top: 10px;
}

.ap-font {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px;
}

.ap-font__btn {
  padding: 5px 0;
  border: none;
  border-radius: 6px;
  background: var(--c-sunken);
  color: var(--c-text-faint);
  font-family: var(--font-ui);
  font-size: 10px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  -webkit-tap-highlight-color: transparent;

  &:hover {
    background: var(--c-border);
    color: var(--c-text);
  }
}

.ap-font__btn--on {
  background: var(--c-text);
  color: #ffffff;
  font-weight: 600;
}

/* 右：内容 */
.ap-content {
  flex: 1;
  min-width: 0;
  min-height: 0;
  background: #ffffff;
  overflow: hidden;
}

.ap-content__inner {
  height: 100%;
  overflow-y: auto;
  padding: 18px 20px;
  scrollbar-width: thin;
  scrollbar-color: #d1d1d6 transparent;

  &::-webkit-scrollbar {
    width: 5px;
  }

  &::-webkit-scrollbar-thumb {
    background: #d1d1d6;
    border-radius: 3px;
  }
}

/* ── 底部 ── */
.ap-foot {
  padding: 10px 18px;
  background: var(--c-bar);
  border-top: 0.5px solid #efefef;
  text-align: center;
}

.ap-foot__text {
  font-size: 11px;
  font-weight: 400;
  color: var(--c-text-faint);
  line-height: 1.5;
}

@media (max-width: 620px) {
  .ap-sidebar {
    width: 64px;
    padding: 10px 6px;
  }

  .ap-nav {
    padding: 9px 3px;
  }

  .ap-nav__label {
    font-size: 10px;
  }

  .ap-content__inner {
    padding: 14px 14px;
  }

  .ap-top {
    padding: 10px 13px;
  }

  .ap-top__center {
    display: none;
  }

  .ap-font {
    grid-template-columns: 1fr 1fr;
  }
}
